// 0DAB:0B95: void Calibrate_CPU_And_Video_Timing_0B95()
// Called from:
//      Initialize_Graphics_Runtime_0C8F
// Sol: Summary: Measure the native machine's drawing and delay speed.
// Sol: Outline: Count work around display timing events and store values used by later waits and effects.
void Calibrate_CPU_And_Video_Timing_0B95()
{
	// Sol: Audit: timer snapshots, four-tick window, signed calibration and10000
	// Sol: status samples match under32-bit DWORD/16-bit WORD bindings. This models
	// Sol: operations, not instruction timing of a compiled C spin loop; replace in port.
	// Sol: 0DAB:0B95-0C28. This is the 32-bit BIOS timer tick count at
	// Sol: physical address 0000:046C (equivalent to BDA 0040:006C).
	volatile unsigned long far *BiosTickCounter = (unsigned long far *)0x0000046CL;
	seg3092->VideoStatusInactiveLevel = 0x00;

	Disable_CPU_Interrupts_1FAD(); // CLI
	unsigned long InitialTick = *BiosTickCounter;
	Enable_CPU_Interrupts_1F9C();  // STI
	while (*BiosTickCounter == InitialTick)
		;

	Disable_CPU_Interrupts_1FAD(); // Make the four-tick target snapshot atomic.
	unsigned long TargetTick = *BiosTickCounter + 0x04L;
	Enable_CPU_Interrupts_1F9C();

	unsigned short SpinBlocks = 0x00;
	while (*BiosTickCounter < TargetTick)
	{
		SpinBlocks++;
		for (volatile unsigned short InnerSpin = 0x00C8; InnerSpin != 0x00; InnerSpin--)
			;
	}

	// Sol: 0DAB:0C29-0C4F uses the runtime's signed 32-bit multiply/divide
	// Sol: helpers to calculate (SpinBlocks * 455) / 10000.
	seg3092->CpuTimingCalibration =
		(unsigned short)(((signed long)(signed short)SpinBlocks * 0x01C7L) / 0x2710L);

	// Sol: 0DAB:0C50-0C88 samples EGA input-status port 3DAh bit 3 exactly
	// Sol: 10,000 times. Store 1 only when high samples form the majority.
	unsigned short RetraceHighSamples = 0x00;
	unsigned short RetraceLowSamples = 0x00;
	for (unsigned short Sample = 0x00; Sample < 0x2710; Sample++)
	{
		if (Read_EGA_Vertical_Retrace_Bit_0B26() != 0x00)
			RetraceHighSamples++;
		else
			RetraceLowSamples++;
	}

	if (RetraceHighSamples > RetraceLowSamples)
		seg3092->VideoStatusInactiveLevel = 0x01;
}

