// 0DAB:0C8F: void Initialize_Graphics_Runtime_0C8F()
// Called from:
//      main at 0D27:011C
// Sol: Summary: Set up the original display and timing services.
// Sol: Outline: Configure the selected graphics mode and runtime flags, install required handlers, and calibrate timing.
void Initialize_Graphics_Runtime_0C8F()
{
	// Sol: Audit: complete0C8F..0D11 call/store sequence matches, including WORD
	// Sol: subtraction before signed divide/clamp. BIOS/runtime callees remain contracts.
	// Sol: Preserve the reusable 3092:4614 file-buffer pointer in the runtime,
	// Sol: select the detected adapter, and enter its BIOS video mode.
	Register_File_Buffer_Pointer_1D8C(&seg3092->Ptr_File_To_Memory_Block);
	Set_Runtime_Graphics_Adapter_2CE1(seg3EDB->GraphicsAdapter);
	Set_BIOS_Video_Mode_0B73(
		seg3EDB->BiosVideoModeByGraphicsAdapter[seg3EDB->GraphicsAdapter]);
	Graphics_Set_Screen_To_Black();

	Calibrate_CPU_And_Video_Timing_0B95();

	// Sol: 0DAB:0CD6-0CFA converts the raw CPU calibration into the busy-wait
	// Sol: multiplier used by sound and timing loops, clamped to at least one.
	signed short BusyWaitScale =
		(signed short)(seg3092->CpuTimingCalibration - 0x04) / 0x06;
	if (BusyWaitScale < 0x01)
		BusyWaitScale = 0x01;
	seg3EDB->BusyWaitScale = (unsigned short)BusyWaitScale;

	Configure_Graphics_For_Adapter_2CF7();
	Install_DOS_Interrupt_24_Handler_3C82(DOS_Critical_Error_Handler_0D26);
}

